// Regenerates packages/react/src/internal/a11y/wcag.ts from W3C's machine-readable WCAG 2.2 data.
// Run by hand, never in `pnpm check`: the criteria change only with a new WCAG version, and the
// check must stay offline. Review the diff before committing it.
//
//   node scripts/sync-wcag.mjs                  fetch https://www.w3.org/WAI/WCAG22/wcag.json
//   node scripts/sync-wcag.mjs --file wcag.json use a local copy
//
// Terms (w3c/wcag, 11ty/json/README.md): use is allowed with attribution and a link, without
// changing the content. The generated file therefore holds W3C data only, verbatim; senui's own
// additions (such as the focusable baseline) live elsewhere.
import { readFileSync, writeFileSync } from 'node:fs';
import * as prettier from 'prettier';

const SOURCE = 'https://www.w3.org/WAI/WCAG22/wcag.json';
const VERSION = '2.2';
const OUT = 'packages/react/src/internal/a11y/wcag.ts';

const fileArg = process.argv.indexOf('--file');
const data =
  fileArg === -1
    ? await (async () => {
        const response = await fetch(SOURCE);
        if (!response.ok) throw new Error(`${SOURCE}: HTTP ${String(response.status)}`);
        return response.json();
      })()
    : JSON.parse(readFileSync(process.argv[fileArg + 1], 'utf8'));

const criteria = [];
for (const principle of data.principles ?? []) {
  for (const guideline of principle.guidelines ?? []) {
    for (const sc of guideline.successcriteria ?? []) {
      // A criterion removed from 2.2 (4.1.1 Parsing) is listed without "2.2" in its versions.
      if (!sc.versions?.includes(VERSION)) continue;
      if (!/^\d+\.\d+\.\d+$/.test(sc.num) || !['A', 'AA', 'AAA'].includes(sc.level)) {
        throw new Error(
          `Unexpected criterion shape: ${JSON.stringify({ num: sc.num, level: sc.level })}`,
        );
      }
      criteria.push({ num: sc.num, level: sc.level, title: sc.handle });
    }
  }
}
// The 2.2 Recommendation has 86 criteria. A different count means the source changed shape or
// content; stop and look rather than write it.
if (criteria.length !== 86) {
  throw new Error(`Expected 86 WCAG ${VERSION} criteria, found ${String(criteria.length)}`);
}

const quote = (s) => `'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
const today = new Date().toISOString().slice(0, 10);
const rows = criteria
  .map((c) => `  ${quote(c.num)}: { level: ${quote(c.level)}, title: ${quote(c.title)} },`)
  .join('\n');

const source = `// GENERATED by scripts/sync-wcag.mjs on ${today}. Do not edit; rerun the script.
//
// Source: Web Content Accessibility Guidelines (WCAG) 2.2, https://www.w3.org/TR/WCAG22/
// Data: ${SOURCE}
// Copyright © World Wide Web Consortium. Used under the W3C Document License,
// https://www.w3.org/copyright/document-license/. Content is unchanged; only success criteria
// that apply to WCAG ${VERSION} are included.

/** Every WCAG ${VERSION} success criterion, with its conformance level and W3C short title. */
export const WCAG22 = {
${rows}
} as const satisfies Record<string, { level: 'A' | 'AA' | 'AAA'; title: string }>;

/** A WCAG ${VERSION} success criterion number, e.g. \`'2.4.7'\`. */
export type WcagCriterion = keyof typeof WCAG22;
`;
const options = await prettier.resolveConfig(OUT);
writeFileSync(OUT, await prettier.format(source, { ...options, filepath: OUT }));
console.log(`Wrote ${String(criteria.length)} WCAG ${VERSION} criteria to ${OUT}.`);
